// BillingServiceServer is the server API for BillingService service.
// All implementations must embed UnimplementedBillingServiceServer
// for forward compatibility.
//
// BillingService handles financial accounting: ledger entries, org balances,
// payouts, reconciliation, revenue reporting, and user spending history.
// Consumes events from cg-payments, cg-orders, cg-booking, cg-workshop via Kafka.
type BillingServiceServer interface {
	// === Ledger ===
	RecordLedgerEntry(context.Context, *RecordLedgerEntryRequest) (*RecordLedgerEntryResponse, error)
	ListLedgerEntries(context.Context, *ListLedgerEntriesRequest) (*ListLedgerEntriesResponse, error)
	// === Org balances ===
	GetOrgBalance(context.Context, *GetOrgBalanceRequest) (*GetOrgBalanceResponse, error)
	// === Payouts ===
	InitiatePayout(context.Context, *InitiatePayoutRequest) (*InitiatePayoutResponse, error)
	GetPayoutHistory(context.Context, *GetPayoutHistoryRequest) (*GetPayoutHistoryResponse, error)
	// === Reconciliation ===
	ReconcileTransaction(context.Context, *ReconcileTransactionRequest) (*ReconcileTransactionResponse, error)
	// === Reporting ===
	GetOrgStatement(context.Context, *GetOrgStatementRequest) (*GetOrgStatementResponse, error)
	GetRevenueStats(context.Context, *GetRevenueStatsRequest) (*GetRevenueStatsResponse, error)
	// GetStatement returns cursor-paginated ledger entries for any subject
	// (user or organization). Use this for "my spending history" on mobile and
	// "org earnings statement" on web.
	GetStatement(context.Context, *GetStatementRequest) (*GetStatementResponse, error)
	// GetUserBalance returns aggregate spending totals for a user.
	GetUserBalance(context.Context, *GetUserBalanceRequest) (*GetUserBalanceResponse, error)
	// ListSpending returns enriched spending entries for a user: each entry
	// includes entity_type, entity_id, amount, currency, and a counterparty_name
	// resolved from upstream services. Intended for the mobile "spending feed".
	ListSpending(context.Context, *ListSpendingRequest) (*ListSpendingResponse, error)
	// GetWalletBalance returns the user's deductible bonus/cashback balance.
	GetWalletBalance(context.Context, *GetWalletBalanceRequest) (*GetWalletBalanceResponse, error)
	// DebitWallet subtracts amount from the user's bonus wallet. Idempotent on
	// idempotency_key. Called by cg-payments StartPayment before the provider call.
	DebitWallet(context.Context, *DebitWalletRequest) (*DebitWalletResponse, error)
	// CreditWallet adds bonus/cashback to the user's wallet. Idempotent on
	// idempotency_key. Called by the payment_confirmed Kafka consumer.
	CreditWallet(context.Context, *CreditWalletRequest) (*CreditWalletResponse, error)
	// CreditOrgBalance credits an organization's available balance directly
	// (insurance-order payout or manual adjustment). Idempotent on idempotency_key.
	CreditOrgBalance(context.Context, *CreditOrgBalanceRequest) (*CreditOrgBalanceResponse, error)
	// CreditInsuranceOrder resolves organization and amount from the request/bid
	// owners, then credits the durable billing ledger exactly once per request.
	CreditInsuranceOrder(context.Context, *CreditInsuranceOrderRequest) (*CreditInsuranceOrderResponse, error)
	// GetInsuranceOrderCreditStatus returns billing-owned state for one request.
	GetInsuranceOrderCreditStatus(context.Context, *GetInsuranceOrderCreditStatusRequest) (*GetInsuranceOrderCreditStatusResponse, error)
	// InitiateOrgCardBinding starts a card-binding flow and returns a redirect URL.
	InitiateOrgCardBinding(context.Context, *InitiateOrgCardBindingRequest) (*InitiateOrgCardBindingResponse, error)
	// ConfirmOrgCardBinding finalizes a card binding after the provider callback.
	ConfirmOrgCardBinding(context.Context, *ConfirmOrgCardBindingRequest) (*ConfirmOrgCardBindingResponse, error)
	// ListOrgCards returns an organization's payout cards.
	ListOrgCards(context.Context, *ListOrgCardsRequest) (*ListOrgCardsResponse, error)
	// DeleteOrgCard soft-deletes a payout card (status -> "deleted").
	DeleteOrgCard(context.Context, *DeleteOrgCardRequest) (*DeleteOrgCardResponse, error)
	// DeclareEscrowWork marks the service as delivered. Only an authenticated
	// member of the recipient organization may call it.
	DeclareEscrowWork(context.Context, *DeclareEscrowWorkRequest) (*DeclareEscrowWorkResponse, error)
	// ConfirmEscrowDelivery confirms delivery and releases the escrowed amount.
	// Only the authenticated payer may call it; service identities are forbidden.
	// Request/bid escrow additionally requires a one-time, expiring challenge
	// bound server-side to payer + deal + amount + this exact action.
	ConfirmEscrowDelivery(context.Context, *ConfirmEscrowDeliveryRequest) (*ConfirmEscrowDeliveryResponse, error)
	// StartEscrowReleaseChallenge sends the protected confirmation challenge to
	// the authenticated payer's verified contact. The server resolves the payer
	// and amount from the immutable deal snapshot; callers cannot supply either.
	StartEscrowReleaseChallenge(context.Context, *StartEscrowReleaseChallengeRequest) (*StartEscrowReleaseChallengeResponse, error)
	// AdminConfirmEscrowDelivery confirms delivery on behalf of the payer. Only
	// the canonical cg-bff admin caller with a human admin identifier may call it.
	AdminConfirmEscrowDelivery(context.Context, *AdminConfirmEscrowDeliveryRequest) (*AdminConfirmEscrowDeliveryResponse, error)
	// OpenEscrowDispute freezes ordinary settlement and opens a dispute. Only the
	// authenticated payer may call it. No elapsed-time path releases escrow.
	OpenEscrowDispute(context.Context, *OpenEscrowDisputeRequest) (*OpenEscrowDisputeResponse, error)
	// Deprecated: Do not use.
	// ReleaseEscrowAdvance is retained only for published v1 wire compatibility.
	// New and upgraded servers always reject it with FAILED_PRECONDITION; safe
	// payment releases only after protected confirmation or dispute resolution.
	ReleaseEscrowAdvance(context.Context, *ReleaseEscrowAdvanceRequest) (*ReleaseEscrowAdvanceResponse, error)
	// SettleEscrowDispute resolves a dispute by either fully releasing the
	// remaining amount or fully returning it. Split settlement is not supported.
	// Only the canonical cg-bff admin caller with a human admin identifier may
	// call it.
	SettleEscrowDispute(context.Context, *SettleEscrowDisputeRequest) (*SettleEscrowDisputeResponse, error)
	// GetEscrowDeal returns one deal. Only its payer, a member of its recipient
	// organization, or an authorized admin may call it.
	GetEscrowDeal(context.Context, *GetEscrowDealRequest) (*GetEscrowDealResponse, error)
	// ListOrganizationEscrowDeals returns deals for an organization. Only a
	// verified member of that organization or an authorized admin may call it.
	ListOrganizationEscrowDeals(context.Context, *ListOrganizationEscrowDealsRequest) (*ListOrganizationEscrowDealsResponse, error)
	// ListEscrowDeals is the global operational queue. It is service-token only;
	// the admin BFF authenticates and authorizes the human platform administrator
	// before adapting this projection.
	ListEscrowDeals(context.Context, *ListEscrowDealsRequest) (*ListEscrowDealsResponse, error)
	// ListPayerEscrowDeals returns the authenticated payer's safe-payment
	// history. The service derives and verifies payer identity from the JWT;
	// service identities may provide payer_user_id for admin/internal adapters.
	ListPayerEscrowDeals(context.Context, *ListPayerEscrowDealsRequest) (*ListPayerEscrowDealsResponse, error)
	// BindEscrowPerformer names the organization that will receive a deal whose
	// performer was still unknown when the payer paid.
	//
	// Dispatched work (roadside assistance and other fixed-price services) is
	// paid up front and only then offered to performers, so the hold cannot name
	// a recipient at capture time. The owner service calls this once the order is
	// assigned. Binding is single-shot: a deal that already names an organization
	// rejects a second call, and a deal can never settle while unbound.
	BindEscrowPerformer(context.Context, *BindEscrowPerformerRequest) (*BindEscrowPerformerResponse, error)
	mustEmbedUnimplementedBillingServiceServer()
}

